import { Box } from "@/shared/ui/layout/Box";

interface OpStateAttrs { "data-op"?: string; "data-mark"?: string; "data-role"?: string }
interface NodeOp { op: string; node?: string; nodes?: string[]; edge?: [string, string]; at?: [string, string] }
interface TreeFrame {
  structure: "tree";
  nodes: { id: string; value: number | string; parent?: string }[];
  ops?: NodeOp[];
  marks?: Record<string, string>;
}

function nodeOpStateAttrs(ops: readonly NodeOp[] | undefined, id: string): OpStateAttrs {
  const attrs: OpStateAttrs = {};
  for (const o of ops ?? []) {
    const hit = o.node === id || !!o.nodes?.includes(id) || !!o.edge?.includes(id) || !!o.at?.includes(id);
    if (hit) attrs["data-op"] = o.op;
  }
  return attrs;
}
function markStateAttrs(marks: Record<string, string> | undefined, key: string): OpStateAttrs {
  const mark = marks?.[key];
  return mark ? { "data-mark": mark } : {};
}

const TREE_VIEW = 320;
const PAD = 34;
interface LayoutNode { id: string; parent?: string }
function treeLayout(nodes: readonly LayoutNode[]): Record<string, { x: number; y: number }> {
  const pos: Record<string, { x: number; y: number }> = {};
  if (nodes.length === 0) return pos;

  const ids = new Set(nodes.map((n) => n.id));
  const children = new Map<string, string[]>();
  for (const n of nodes) children.set(n.id, []);
  const roots: string[] = [];
  for (const n of nodes) {
    if (n.parent !== undefined && ids.has(n.parent)) children.get(n.parent)!.push(n.id);
    else roots.push(n.id);
  }

  const depth = new Map<string, number>();
  const rawX = new Map<string, number>();
  let slot = 0;
  const place = (rootId: string): void => {
    const stack: { id: string; d: number; phase: 0 | 1 }[] = [{ id: rootId, d: 0, phase: 0 }];
    while (stack.length) {
      const top = stack[stack.length - 1];
      const kids = children.get(top.id) ?? [];
      if (top.phase === 0) {
        depth.set(top.id, top.d);
        top.phase = 1;
        for (let i = kids.length - 1; i >= 0; i--) stack.push({ id: kids[i], d: top.d + 1, phase: 0 });
      } else {
        stack.pop();
        if (kids.length === 0) rawX.set(top.id, slot++);
        else rawX.set(top.id, (rawX.get(kids[0])! + rawX.get(kids[kids.length - 1])!) / 2);
      }
    }
  };
  for (const r of roots) place(r);

  const maxX = Math.max(1, slot - 1);
  const maxD = Math.max(1, ...depth.values());
  const inner = TREE_VIEW - 2 * PAD;
  for (const n of nodes) {
    const rx = rawX.get(n.id) ?? 0;
    const d = depth.get(n.id) ?? 0;
    pos[n.id] = {
      x: slot <= 1 ? TREE_VIEW / 2 : PAD + (rx / maxX) * inner,
      y: PAD + (d / maxD) * inner,
    };
  }
  return pos;
}

const NODE_R = 16;
export function TreeView({
  frame = {
    structure: "tree",
    nodes: [{ id: "a", value: 8 }, { id: "b", value: 3, parent: "a" }, { id: "c", value: 12, parent: "a" }, { id: "d", value: 1, parent: "b" }],
    ops: [{ op: "visit", node: "b" }],
    marks: { a: "visited" },
  },
}: { frame?: TreeFrame }) {
  const { nodes, ops, marks } = frame;
  const pos = treeLayout(nodes);
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const nodeOps = (ops ?? []).filter((o) => o.op !== "rotate");

  return (
    <Box className="tree-view" role="img" aria-label="tree">
      {nodes.length === 0 ? (
        <Box className="tree-empty" aria-label="empty">
          (empty)
        </Box>
      ) : (
        <svg viewBox={`0 0 ${TREE_VIEW} ${TREE_VIEW}`} className="tree-svg" role="presentation">
          {nodes.map((nd) => {
            const p = pos[nd.id];
            const parent = nd.parent !== undefined ? byId.get(nd.parent) : undefined;
            const pp = parent ? pos[parent.id] : undefined;
            if (!p || !pp) return null;
            return <line key={`e-${nd.id}`} className="tree-edge" x1={pp.x} y1={pp.y} x2={p.x} y2={p.y} />;
          })}
          {nodes.map((nd) => {
            const p = pos[nd.id];
            if (!p) return null;
            const attrs = { ...nodeOpStateAttrs(nodeOps, nd.id), ...markStateAttrs(marks, nd.id) };
            return (
              <g key={nd.id} transform={`translate(${p.x} ${p.y})`}>
                <circle className="tree-node" r={NODE_R} {...attrs} />
                <text className="tree-node-label" textAnchor="middle" dominantBaseline="central">
                  {nd.value}
                </text>
              </g>
            );
          })}
        </svg>
      )}
    </Box>
  );
}
